// Edit these once. Secrets (API keys, tokens) live in n8n Credentials, never here.
const CONFIG = {
  MEET_WHATSAPP: '91XXXXXXXXXX',          // Meet's WhatsApp number: country code + number, no +
  WA_PHONE_NUMBER_ID: 'XXXXXXXXXXXXXXX',  // Meta WhatsApp Cloud API → phone number ID
  WA_API: 'https://graph.facebook.com/v21.0',
  SLACK_CHANNEL: 'C0AKT2RDQNA',
  MODEL_FAST: 'claude-haiku-4-5-20251001'
};
return $input.all().map(i => ({ json: { ...i.json, CONFIG } }));

return $input.all().map(i => {
  const C = i.json.CONFIG;
  const body = String(i.json.text || i.json.textAsHtml || i.json.html || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 12000);
  return { json: {
    emailId: i.json.id,
    subject: i.json.subject,
    claudeRequest: {
      model: C.MODEL_FAST,
      max_tokens: 600,
      system: 'You extract Airbnb reservation details from host confirmation emails for The Empire Stays. Reply with one JSON object and nothing else.',
      messages: [{ role: 'user', content: 'Subject: ' + i.json.subject + '\n\n' + body + '\n\nReturn JSON with keys: confirmation_code (string), guest_first_name (string), listing_name (string, as written in the email), check_in (YYYY-MM-DD), check_out (YYYY-MM-DD), guests (number), payout_inr (number, host payout in rupees). Use null for anything not in the email.' }]
    }
  } };
});

const PORTFOLIO = [
  { code: 'OS A2106', name: 'White Island*21', keys: ['white island'] },
  { code: 'Sol C 2103', name: 'Coastline Studio*21', keys: ['coastline'] },
  { code: 'PCR T5 1901', name: 'Heaven*19', keys: ['heaven'] },
  { code: 'PCR T4 3507', name: 'NYC*35', keys: ['nyc'] },
  { code: 'JG T1 1402', name: 'Paradise*142', keys: ['paradise*142', 'paradise 142', 'paradise °142', '142'] },
  { code: 'JG T1 1404', name: 'Paradise*144', keys: ['paradise*144', 'paradise 144', 'paradise °144', '144'] },
  { code: 'PCE T4 3006', name: 'Sky*30', keys: ['sky*30', 'sky 30', 'sky °30'] },
  { code: 'PRP3 S2 1701', name: 'Sky Escape', keys: ['sky escape'] },
  { code: 'RBA1704', name: 'Terra Blush*17', keys: ['terra blush'] },
  { code: 'SKYLINE', name: 'Skyline Hideaway', keys: ['skyline'] }
];
const prev = $('Prepare extraction').all();
return $input.all().map((it, idx) => {
  const txt = (it.json.content || []).map(c => c.text || '').join('');
  let b = {};
  try { b = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); } catch (e) { b = { parse_error: true }; }
  const name = String(b.listing_name || '').toLowerCase();
  const hit = PORTFOLIO.find(p => p.keys.some(k => name.includes(k)));
  return { json: {
    confirmation_code: b.confirmation_code || null,
    guest_first_name: b.guest_first_name || null,
    listing_display: hit ? hit.name : (b.listing_name || 'Unknown listing'),
    listing_code: hit ? hit.code : null,
    check_in: b.check_in || null,
    check_out: b.check_out || null,
    guests: b.guests == null ? null : b.guests,
    payout_inr: b.payout_inr == null ? null : b.payout_inr,
    email_id: prev[idx] ? prev[idx].json.emailId : null
  } };
});

const C = $('Config').first().json.CONFIG;
const fmt = d => d ? new Date(d).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', timeZone: 'Asia/Kolkata' }) : '?';
const out = [];
for (const it of $input.all()) {
  const b = it.json;
  if (!b.is_new) continue; // same email polled twice: stay quiet
  const dates = fmt(b.check_in) + ' → ' + fmt(b.check_out) + (b.guests ? ' · ' + b.guests + ' guests' : '');
  out.push({ json: {
    kind: 'whatsapp',
    url: C.WA_API + '/' + C.WA_PHONE_NUMBER_ID + '/messages',
    body: {
      messaging_product: 'whatsapp',
      to: C.MEET_WHATSAPP,
      type: 'template',
      template: {
        name: 'tes_new_booking_alert',
        language: { code: 'en' },
        components: [{ type: 'body', parameters: [
          { type: 'text', text: b.listing_name || 'New listing' },
          { type: 'text', text: b.guest_first_name || 'Guest' },
          { type: 'text', text: dates },
          { type: 'text', text: b.confirmation_code || 'n/a' }
        ] }]
      }
    }
  } });
  out.push({ json: {
    kind: 'slack',
    body: { channel: C.SLACK_CHANNEL, text: '01A · New booking ' + (b.confirmation_code || '') + ' · ' + (b.listing_name || '') + ' · ' + (b.guest_first_name || '') + ' · ' + dates + ' → asked Meet for guest WhatsApp' }
  } });
}
return out;
